import re
from typing import NamedTuple

class TemplateError(Exception):
    pass

class TemplateSyntaxError(TemplateError):
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")

class TemplateRenderError(TemplateError):
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")

class Token(NamedTuple):
    kind: str
    value: str
    lineno: int

# Tag definitions: start_delim, end_delim, kind
TAG_DEFS = [
    ('{{', '}}', 'var'),
    ('{%', '%}', 'block'),
    ('{#', '#}', 'comment'),
]

TAG_START_RE = re.compile(r'\{\{|\{%|\{#')

def tokenize(source: str) -> list[Token]:
    tokens = []
    pos = 0
    lineno = 1
    length = len(source)
    current_text = []
    current_text_start_line = 1

    def flush_text():
        if current_text:
            tokens.append(Token('text', ''.join(current_text), current_text_start_line))
            current_text.clear()

    while pos < length:
        # Check for tag start
        if source[pos] == '{':
            tag_type = None
            tag_start = None
            tag_len = 0
            for start_delim, end_delim, kind in TAG_DEFS:
                if source.startswith(start_delim, pos):
                    tag_type = kind
                    tag_start = start_delim
                    tag_len = len(start_delim)
                    break

            if tag_type:
                # Find the end delimiter
                end_delim = None
                for start_delim, end_delim, kind in TAG_DEFS:
                    if start_delim == tag_start:
                        break

                end_pos = source.find(end_delim, pos + tag_len)
                if end_pos == -1:
                    raise TemplateSyntaxError(f"unclosed tag {tag_start}", lineno)

                # Flush any pending text
                flush_text()

                # Extract tag content
                inner_content = source[pos + tag_len:end_pos].strip()

                if tag_type != 'comment':
                    tokens.append(Token(tag_type, inner_content, lineno))

                # Update position and line number
                # Count newlines in the consumed part (including the delimiters)
                consumed_part = source[pos:end_pos + len(end_delim)]
                lineno += consumed_part.count('\n')
                pos = end_pos + len(end_delim)

                # Set start line for next potential text token
                current_text_start_line = lineno
                continue

        # It's text
        if not current_text:
            current_text_start_line = lineno
        current_text.append(source[pos])
        if source[pos] == '\n':
            lineno += 1
        pos += 1

    flush_text()
    return tokens
