import re
from .lexer import TemplateSyntaxError, tokenize

# --- Lexer for tag contents ---

KEYWORDS = {'and', 'or', 'not', 'in'}

def _tokenize_content(content: str) -> list[tuple[str, str, int]]:
    """Returns list of (kind, value) tuples. Kind: ID, INT, STR, OP, EOF."""
    tokens = []
    pos = 0
    n = len(content)

    # Operators sorted by length descending to match longest first
    OPS = ['==', '!=', '<=', '>=', '|', ':', '.', '<', '>', '(', ')']

    while pos < n:
        if content[pos].isspace():
            pos += 1
            continue

        # Try match operators
        matched_op = None
        for op in OPS:
            if content.startswith(op, pos):
                matched_op = op
                break

        if matched_op:
            tokens.append(('OP', matched_op))
            pos += len(matched_op)
            continue

        # Match number: optional sign followed by digits
        if content[pos] == '-' or content[pos].isdigit():
            m = re.match(r'-?\d+', content[pos:])
            if m:
                tokens.append(('INT', m.group(0)))
                pos += len(m.group(0))
                continue
            else:
                raise TemplateSyntaxError("unexpected character", 0)

        # Match string
        if content[pos] in ('"', "'"):
            quote = content[pos]
            end_pos = content.find(quote, pos + 1)
            if end_pos == -1:
                raise TemplateSyntaxError("unterminated string literal", 0)
            str_val = content[pos + 1:end_pos]
            tokens.append(('STR', str_val))
            pos = end_pos + 1
            continue

        # Match identifier
        if content[pos].isalpha() or content[pos] == '_':
            m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', content[pos:])
            if m:
                word = m.group(0)
                if word in KEYWORDS:
                    tokens.append(('KEYWORD', word))
                else:
                    tokens.append(('ID', word))
                pos += len(word)
                continue

        raise TemplateSyntaxError(f"unexpected character: '{content[pos]}'", 0)

    tokens.append(('EOF', None))
    return tokens

# --- AST Nodes ---

class Node:
    pass

class TextNode(Node):
    def __init__(self, text):
        self.text = text

class ExprNode(Node):
    pass

class LiteralNode(ExprNode):
    def __init__(self, value):
        self.value = value

class VariableNode(ExprNode):
    def __init__(self, name, segments):
        self.name = name
        self.segments = segments

class FilterNode(ExprNode):
    def __init__(self, source, name, arg):
        self.source = source
        self.name = name
        self.arg = arg

class ComparisonNode(ExprNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class NotNode(ExprNode):
    def __init__(self, operand):
        self.operand = operand

class AndNode(ExprNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class OrNode(ExprNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

# Statement Nodes

class StatementNode(Node):
    pass

class ForNode(StatementNode):
    def __init__(self, var_name, expr, body, else_body, lineno):
        self.var_name = var_name
        self.expr = expr
        self.body = body
        self.else_body = else_body
        self.lineno = lineno

class IfNode(StatementNode):
    def __init__(self, branches, else_body, lineno):
        # branches: list of (ConditionExpr, list[Node], int) where int is lineno of condition
        self.branches = branches
        self.else_body = else_body
        self.lineno = lineno

class ContentParser:
    def __init__(self, toks, lineno):
        self.toks = toks
        self.pos = 0
        self.lineno = lineno

    def current(self):
        if self.pos >= len(self.toks):
            return ('EOF', None)
        return self.toks[self.pos]

    def consume(self):
        t = self.toks[self.pos]
        self.pos += 1
        return t

    def expect_keyword(self, kw):
        t = self.current()
        if t[0] != 'KEYWORD' or t[1] != kw:
            raise TemplateSyntaxError(f"expected '{kw}'", self.lineno)
        self.consume()

    def expect_id(self):
        t = self.current()
        if t[0] != 'ID':
            raise TemplateSyntaxError("expected identifier", self.lineno)
        self.consume()
        return t

    def expect_eof(self):
        if self.current()[0] != 'EOF':
            raise TemplateSyntaxError("unexpected content", self.lineno)

    def parse_value_expr(self):
        return self._atom_filters()

    def parse_condition(self):
        return self._or_expr()

    def _or_expr(self):
        left = self._and_expr()
        while self.current()[0] == 'KEYWORD' and self.current()[1] == 'or':
            self.consume()
            right = self._and_expr()
            left = OrNode(left, right)
        return left

    def _and_expr(self):
        left = self._not_expr()
        while self.current()[0] == 'KEYWORD' and self.current()[1] == 'and':
            self.consume()
            right = self._not_expr()
            left = AndNode(left, right)
        return left

    def _not_expr(self):
        if self.current()[0] == 'KEYWORD' and self.current()[1] == 'not':
            self.consume()
            operand = self._not_expr() 
            return NotNode(operand)
        return self._comparison()

    def _comparison(self):
        left = self._value_expr()
        if self.current()[0] == 'OP' and self.current()[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = self.consume()[1]
            right = self._value_expr()
            return ComparisonNode(left, op, right)
        return left

    def _value_expr(self):
        return self._atom_filters()

    def _atom_filters(self):
        val = self._atom()
        while self.current()[0] == 'OP' and self.current()[1] == '|':
            self.consume()
            filter_name_tok = self.expect_id()
            name = filter_name_tok.value

            arg = None
            if self.current()[0] == 'OP' and self.current()[1] == ':':
                self.consume()
                arg = self._literal_arg()

            val = FilterNode(val, name, arg)
        return val

    def _literal_arg(self):
        t = self.current()
        if t[0] == 'INT':
            self.consume()
            return int(t[1])
        if t[0] == 'STR':
            self.consume()
            return t[1]
        raise TemplateSyntaxError("expected literal argument for filter", self.lineno)

    def _atom(self):
        t = self.current()
        if t[0] == 'STR':
            self.consume()
            return LiteralNode(t[1])
        if t[0] == 'INT':
            self.consume()
            return LiteralNode(int(t[1]))
        if t[0] == 'ID':
            self.consume()
            name = t[1]
            segments = []
            while self.current()[0] == 'OP' and self.current()[1] == '.':
                self.consume()
                seg_t = self.current()
                if seg_t[0] == 'ID':
                    self.consume()
                    segments.append(('name', seg_t[1]))
                elif seg_t[0] == 'INT':
                    self.consume()
                    if seg_t[1].startswith('-'):
                         raise TemplateSyntaxError("negative integer in path segment", self.lineno)
                    segments.append(('int', int(seg_t[1])))
                else:
                    raise TemplateSyntaxError("invalid path segment", self.lineno)

            return VariableNode(name, segments)

        raise TemplateSyntaxError("unexpected token", self.lineno)


class VarStatement:
    def __init__(self, expr, lineno):
        self.expr = expr
        self.lineno = lineno

class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> list:
        nodes = self._parse_nodes(end_keywords=[])
        if self.pos < len(self.tokens):
             # Should have been caught by block handlers
             raise TemplateSyntaxError("unexpected end of file", self.tokens[self.pos].lineno)
        return nodes

    def _parse_nodes(self, end_keywords: list) -> list:
        nodes = []
        while self.pos < len(self.tokens):
            tok = self.tokens[self.pos]

            if tok.kind == 'text':
                nodes.append(TextNode(tok.value))
                self.pos += 1
            elif tok.kind == 'var':
                try:
                    parser = ContentParser(_tokenize_content(tok.value), tok.lineno)
                    expr = parser.parse_value_expr()
                    parser.expect_eof()
                    nodes.append(VarStatement(expr, tok.lineno))
                except TemplateSyntaxError as e:
                    raise TemplateSyntaxError(e.message, tok.lineno)
                self.pos += 1
            elif tok.kind == 'block':
                content = tok.value
                lineno = tok.lineno

                # Check if this is an end tag
                first_word = content.split(' ')[0] if content else ''

                if first_word in end_keywords:
                    return nodes

                stmt = self._parse_block_statement(content, lineno)
                nodes.append(stmt)
            else:
                self.pos += 1

        if end_keywords:
            return nodes

        return nodes

    def _parse_block_statement(self, content: str, lineno: int):
        toks = _tokenize_content(content)
        if not toks or toks[0][0] != 'KEYWORD':
             raise TemplateSyntaxError("invalid block start", lineno)

        keyword = toks[0][1]

        if keyword == 'for':
            return self._handle_for(lineno)
        elif keyword == 'if':
            return self._handle_if(lineno)
        else:
            raise TemplateSyntaxError(f"unknown statement '{keyword}'", lineno)

    def _handle_for(self, lineno: int):
        tok = self.tokens[self.pos]
        content = tok.value
        parser = ContentParser(_tokenize_content(content), lineno)

        parser.expect_keyword('for')
        var_tok = parser.expect_id()
        var_name = var_tok.value
        parser.expect_keyword('in')
        expr = parser.parse_value_expr()
        parser.expect_eof()

        self.pos += 1

        body_nodes = self._parse_nodes(['else', 'endfor'])

        if self.pos >= len(self.tokens):
            raise TemplateSyntaxError("unexpected end of file, missing endfor", lineno)

        end_tok = self.tokens[self.pos]
        if end_tok.kind != 'block':
             raise TemplateSyntaxError("expected endfor or else", end_tok.lineno)

        end_content = end_tok.value
        first_word = end_content.split(' ')[0]

        else_body = None
        if first_word == 'else':
            parser = ContentParser(_tokenize_content(end_content), end_tok.lineno)
            parser.expect_keyword('else')
            parser.expect_eof()
            self.pos += 1

            else_body = self._parse_nodes(['endfor'])

            if self.pos >= len(self.tokens):
                raise TemplateSyntaxError("unexpected end of file, missing endfor", lineno)

            end_tok = self.tokens[self.pos]
            if end_tok.kind != 'block' or end_tok.value.split(' ')[0] != 'endfor':
                raise TemplateSyntaxError("expected endfor", end_tok.lineno)

        elif first_word == 'endfor':
             pass
        else:
             raise TemplateSyntaxError(f"expected else or endfor, got {first_word}", end_tok.lineno)

        if end_tok.value.strip() != 'endfor':
            raise TemplateSyntaxError("malformed endfor tag", end_tok.lineno)

        self.pos += 1

        return ForNode(var_name, expr, body_nodes, else_body, lineno)

    def _handle_if(self, lineno: int):
        tok = self.tokens[self.pos]
        content = tok.value
        parser = ContentParser(_tokenize_content(content), lineno)

        parser.expect_keyword('if')
        cond = parser.parse_condition()
        parser.expect_eof()

        self.pos += 1

        branches = [] 
        else_body = None
        has_else = False

        while True:
            nodes = self._parse_nodes(['elif', 'else', 'endif'])
            branches.append((cond, nodes, tok.lineno)) # Store lineno of the condition tag

            if self.pos >= len(self.tokens):
                raise TemplateSyntaxError("unexpected end of file, missing endif", lineno)

            end_tok = self.tokens[self.pos]
            if end_tok.kind != 'block':
                raise TemplateSyntaxError("expected elif, else, or endif", end_tok.lineno)

            end_content = end_tok.value
            first_word = end_content.split(' ')[0]

            if first_word == 'endif':
                if end_content.strip() != 'endif':
                     raise TemplateSyntaxError("malformed endif tag", end_tok.lineno)
                self.pos += 1
                break

            elif first_word == 'else':
                if has_else:
                    raise TemplateSyntaxError("duplicate else", end_tok.lineno)
                p = ContentParser(_tokenize_content(end_content), end_tok.lineno)
                p.expect_keyword('else')
                p.expect_eof()
                self.pos += 1

                has_else = True

                else_nodes = self._parse_nodes(['endif'])

                if self.pos >= len(self.tokens):
                    raise TemplateSyntaxError("unexpected end of file, missing endif", lineno)

                final_tok = self.tokens[self.pos]
                if final_tok.kind != 'block' or final_tok.value.strip() != 'endif':
                    raise TemplateSyntaxError("expected endif", final_tok.lineno)

                else_body = else_nodes
                self.pos += 1
                break 

            elif first_word == 'elif':
                if has_else:
                    raise TemplateSyntaxError("elif after else", end_tok.lineno)

                p = ContentParser(_tokenize_content(end_content), end_tok.lineno)
                p.expect_keyword('elif')
                cond = p.parse_condition()
                p.expect_eof()
                tok = end_tok # Update tok for next iteration's branch lineno
                self.pos += 1

            else:
                raise TemplateSyntaxError(f"unexpected tag '{first_word}'", end_tok.lineno)

        return IfNode(branches, else_body, lineno)


def parse(source: str) -> list:
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()
