import collections.abc
from .lexer import TemplateRenderError
from .parser import (
    TextNode, VarStatement, ForNode, IfNode,
    LiteralNode, VariableNode, FilterNode,
    ComparisonNode, NotNode, AndNode, OrNode,
    parse
)

def _get_filter_output_text(val):
    if val is None:
        return ""
    return str(val)

def _apply_filter(node: FilterNode, val, lineno):
    name = node.name
    arg = node.arg

    # Syntax errors for filters are handled by parser, but if they slip through or are runtime dependent:
    # Spec: "An unknown filter... is a syntax error." -> Parser should catch.
    # "A filter applied to a value it cannot handle ... is a render error."

    try:
        if name == 'upper':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            return _get_filter_output_text(val).upper()
        elif name == 'lower':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            return _get_filter_output_text(val).lower()
        elif name == 'trim':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            return _get_filter_output_text(val).strip()
        elif name == 'length':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            if val is None: return 0
            try:
                return len(val)
            except TypeError:
                raise TemplateRenderError(f"cannot get length of {type(val).__name__}", lineno)
        elif name == 'first':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            if val is None or len(val) == 0: return None
            return val[0]
        elif name == 'last':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            if val is None or len(val) == 0: return None
            return val[-1]
        elif name == 'reverse':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            if val is None: return None
            if isinstance(val, str):
                return val[::-1]
            else:
                try:
                    return list(reversed(val))
                except TypeError:
                    raise TemplateRenderError(f"cannot reverse {type(val).__name__}", lineno)
        elif name == 'join':
            if arg is None: raise TemplateSyntaxError(f"filter '{name}' requires an argument", lineno)
            if not isinstance(arg, str): raise TemplateSyntaxError(f"filter '{name}' argument must be a string", lineno)
            if val is None: return ""
            try:
                return arg.join(_get_filter_output_text(item) for item in val)
            except TypeError:
                raise TemplateRenderError(f"cannot join {type(val).__name__}", lineno)
        elif name == 'default':
            if arg is None: raise TemplateSyntaxError(f"filter '{name}' requires an argument", lineno)
            if not isinstance(arg, (str, int)): raise TemplateSyntaxError(f"filter '{name}' argument must be string or int", lineno)
            if val is None or val == "":
                return arg
            return val
        elif name == 'truncate':
            if arg is None: raise TemplateSyntaxError(f"filter '{name}' requires an argument", lineno)
            if not isinstance(arg, int): raise TemplateSyntaxError(f"filter '{name}' argument must be an integer", lineno)
            if arg < 0: raise TemplateSyntaxError(f"filter '{name}' argument must be non-negative", lineno)
            text = _get_filter_output_text(val)
            if len(text) > arg:
                return text[:arg] + "..."
            return text
        elif name == 'items':
            if arg is not None: raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)
            if val is None: return []
            if isinstance(val, collections.abc.Mapping):
                return list(val.items())
            else:
                raise TemplateRenderError(f"cannot get items from {type(val).__name__}", lineno)
        else:
            raise TemplateSyntaxError(f"unknown filter '{name}'", lineno)
    except TemplateSyntaxError:
        raise
    except TemplateRenderError:
        raise
    except Exception as e:
        raise TemplateRenderError(f"error applying filter '{name}': {str(e)}", lineno)

def _evaluate_condition(node, context, lineno):
    if isinstance(node, OrNode):
        if _evaluate_condition(node.left, context, lineno):
            return True
        return _evaluate_condition(node.right, context, lineno)
    elif isinstance(node, AndNode):
        if not _evaluate_condition(node.left, context, lineno):
            return False
        return _evaluate_condition(node.right, context, lineno)
    elif isinstance(node, NotNode):
        return not _evaluate_condition(node.operand, context, lineno)
    elif isinstance(node, ComparisonNode):
        left = _get_value(node.left, context, lineno)
        right = _get_value(node.right, context, lineno)
        op = node.op
        try:
            if op == '==': return left == right
            if op == '!=': return left != right
            if op == '<': return left < right
            if op == '<=': return left <= right
            if op == '>': return left > right
            if op == '>=': return left >= right
        except TypeError:
            raise TemplateRenderError(f"cannot compare {type(left).__name__} and {type(right).__name__}", lineno)
        except Exception as e:
            raise TemplateRenderError(f"comparison error: {str(e)}", lineno)
    else:
        val = _get_value(node, context, lineno)
        return bool(val)

def _get_value(node, context, lineno):
    if isinstance(node, LiteralNode):
        return node.value
    elif isinstance(node, VariableNode):
        val = context.get(node.name, None)
        for seg_type, seg_val in node.segments:
            if val is None:
                return None
            if isinstance(val, collections.abc.Mapping):
                key = str(seg_val)
                val = val.get(key, None)
            elif isinstance(val, (list, tuple)):
                if seg_type == 'int':
                    if 0 <= seg_val < len(val):
                        val = val[seg_val]
                    else:
                        return None
                else:
                    return None
            else:
                if seg_type == 'name' and not seg_val.startswith('_'):
                    val = getattr(val, seg_val, None)
                else:
                    return None
        return val
    elif isinstance(node, FilterNode):
        source_val = _get_value(node.source, context, lineno)
        return _apply_filter(node, source_val, lineno)
    else:
        raise TemplateRenderError("invalid value node", lineno)

def _render_nodes(nodes, context, output, lineno):
    for node in nodes:
        _render_node(node, context, output, lineno)

def _render_node(node, context, output, lineno):
    if isinstance(node, TextNode):
        output.append(node.text)
    elif isinstance(node, VarStatement):
        val = _get_value(node.expr, context, node.lineno)
        if val is not None:
            output.append(str(val))
    elif isinstance(node, ForNode):
        iterable = _get_value(node.expr, context, node.lineno)

        items = []
        if iterable is None:
            items = []
        elif isinstance(iterable, collections.abc.Mapping):
            items = list(iterable.keys())
        elif hasattr(iterable, '__iter__'):
            try:
                items = list(iterable)
            except TypeError:
                raise TemplateRenderError(f"cannot iterate over {type(iterable).__name__}", node.lineno)
        else:
            raise TemplateRenderError(f"cannot iterate over {type(iterable).__name__}", node.lineno)

        if not items:
            if node.else_body is not None:
                _render_nodes(node.else_body, context, output, node.lineno)
            return

        length = len(items)

        class ChainContext:
            def __init__(self, local, outer):
                self.local = local
                self.outer = outer
            def get(self, key, default=None):
                if key in self.local:
                    return self.local[key]
                return self.outer.get(key, default)
            def __contains__(self, key):
                return key in self.local or key in self.outer

        for i, item in enumerate(items):
            loop_info = {
                "index": i + 1,
                "index0": i,
                "first": i == 0,
                "last": i == length - 1,
                "length": length
            }
            local_vars = {
                node.var_name: item,
                "loop": loop_info
            }
            new_context = ChainContext(local_vars, context)
            _render_nodes(node.body, new_context, output, node.lineno)

    elif isinstance(node, IfNode):
        matched = False
        for cond, body, branch_lineno in node.branches:
            if _evaluate_condition(cond, context, branch_lineno):
                _render_nodes(body, context, output, node.lineno)
                matched = True
                break

        if not matched and node.else_body is not None:
            _render_nodes(node.else_body, context, output, node.lineno)

class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)
        self.source = source

    def render(self, context: dict | None = None, **kwargs) -> str:
        ctx = {}
        if context is not None:
            ctx.update(context)
        ctx.update(kwargs)

        output = []
        for node in self.nodes:
            lineno = getattr(node, 'lineno', 0)
            try:
                _render_node(node, ctx, output, lineno)
            except TemplateRenderError as e:
                if e.lineno == 0:
                    raise TemplateRenderError(e.message, lineno)
                raise

        return "".join(output)

def render(source: str, context: dict | None = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)
