"""Formula parsing, representation, and evaluation for the sheet engine."""

from __future__ import annotations

from typing import Callable, Set, Tuple, Union


class FormulaError(ValueError):
    """Raised for any problem with a formula's syntax or references."""
    pass


class ErrorValue(str):
    """An error value that compares equal to its text."""

    def __new__(cls, text: str) -> "ErrorValue":
        return str.__new__(cls, text)


ERROR = ErrorValue("#ERROR!")
CYCLE = ErrorValue("#CYCLE!")

# ---- Syntax tree nodes ----

class Number:
    __slots__ = ("value",)

    def __init__(self, value: Union[int, float]):
        self.value = value


class Ref:
    __slots__ = ("name",)  # upper case

    def __init__(self, name: str):
        self.name = name


class Unary:
    __slots__ = ("op", "operand")  # op is '+' or '-'

    def __init__(self, op: str, operand):
        self.op = op
        self.operand = operand


class Binary:
    __slots__ = ("op", "left", "right")  # op in {+, -, *, /}

    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right


# ---- Cell name validation ----

def is_valid_cell(name: str) -> bool:
    if not isinstance(name, str):
        return False
    u = name.upper()
    if not u or not u.isalpha() or u != name:
        return False
    if len(u) != 1:
        return False
    if u not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        return False
    if name != u:
        return False
    return True


def parse_cell(name: str) -> Tuple[str, int]:
    if not isinstance(name, str):
        raise ValueError("invalid cell name")
    u = name.upper()
    if len(u) < 2 or len(u) > 4:
        raise ValueError("invalid cell name")
    letters = []
    digits = []
    i = 0
    while i < len(u) and u[i].isalpha():
        letters.append(u[i])
        i += 1
    while i < len(u) and u[i].isdigit():
        digits.append(u[i])
        i += 1
    if i != len(u) or not letters or not digits:
        raise ValueError("invalid cell name")
    col = "".join(letters)
    if len(col) != 1 or col not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        raise ValueError("invalid cell name")
    row_str = "".join(digits)
    if len(row_str) > 1 and row_str[0] == "0":
        raise ValueError("invalid cell name")
    row = int(row_str)
    if row < 1 or row > 999:
        raise ValueError("invalid cell name")
    return col, row


# ---- Tokenizer ----

def _tokenize(source: str):
    tokens = []
    i = 0
    n = len(source)
    while i < n:
        c = source[i]
        if c in " \t\n\r\f\v":
            i += 1
            continue
        if c in "+-*/()":
            tokens.append(c)
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and source[i].isdigit():
                i += 1
            if i < n and source[i] == ".":
                i += 1
                while i < n and source[i].isdigit():
                    i += 1
            tokens.append(("num", source[start:i]))
            continue
        if c.isalpha():
            start = i
            while i < n and source[i].isalpha():
                i += 1
            if i < n and source[i].isdigit():
                while i < n and source[i].isdigit():
                    i += 1
                tokens.append(("ref", source[start:i].upper()))
            else:
                raise FormulaError("unexpected letters")
            continue
        raise FormulaError("unexpected character")
    return tokens


# ---- Recursive descent parser ----

class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def at_op(self, op):
        tok = self.peek()
        return tok is not None and tok == op

    def parse(self):
        node = self.parse_expr()
        if self.peek() is not None:
            raise FormulaError("trailing tokens")
        return node

    def parse_expr(self):
        left = self.parse_term()
        while True:
            tok = self.peek()
            if tok == "+" or tok == "-":
                self.next()
                right = self.parse_term()
                left = Binary(tok, left, right)
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok == "*" or tok == "/":
                self.next()
                right = self.parse_unary()
                left = Binary(tok, left, right)
            else:
                break
        return left

    def parse_unary(self):
        tok = self.peek()
        if tok == "+" or tok == "-":
            self.next()
            operand = self.parse_unary()
            return Unary(tok, operand)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            raise FormulaError("unexpected end")
        if tok == "(":
            self.next()
            node = self.parse_expr()
            if not self.at_op(")"):
                raise FormulaError("expected )")
            self.next()
            return node
        if isinstance(tok, tuple) and tok[0] == "num":
            self.next()
            s = tok[1]
            if "." in s:
                return Number(float(s))
            return Number(int(s))
        if isinstance(tok, tuple) and tok[0] == "ref":
            self.next()
            try:
                parse_cell(tok[1])
            except ValueError as e:
                raise FormulaError(str(e))
            return Ref(tok[1])
        raise FormulaError("unexpected token")


def parse_formula(source: str):
    if not source:
        raise FormulaError("empty formula")
    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("empty formula")
    parser = _Parser(tokens)
    return parser.parse()


# ---- Analysis ----

def references(tree) -> Set[str]:
    out = set()

    def walk(node):
        if isinstance(node, Ref):
            out.add(node.name)
        elif isinstance(node, Unary):
            walk(node.operand)
        elif isinstance(node, Binary):
            walk(node.left)
            walk(node.right)

    walk(tree)
    return out


def _coerce(v):
    if v is None:
        return 0
    return v


def _combine(op: str, a, b):
    a = _coerce(a)
    b = _coerce(b)
    if isinstance(a, ErrorValue):
        return a
    if isinstance(b, ErrorValue):
        return b
    if isinstance(a, str) or isinstance(b, str):
        return ERROR
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            if b == 0:
                return ERROR
            return float(a / b)
    except Exception:
        return ERROR
    return ERROR


def evaluate(tree, lookup: Callable[[str], object]):
    if isinstance(tree, Number):
        return tree.value
    if isinstance(tree, Ref):
        return lookup(tree.name)
    if isinstance(tree, Unary):
        val = evaluate(tree.operand, lookup)
        val = _coerce(val)
        if isinstance(val, ErrorValue):
            return val
        if isinstance(val, str):
            return ERROR
        if tree.op == "+":
            return +val
        return -val
    if isinstance(tree, Binary):
        left = evaluate(tree.left, lookup)
        right = evaluate(tree.right, lookup)
        return _combine(tree.op, left, right)
    raise FormulaError("unknown node")
