"""Dependency tracking between cells."""

from __future__ import annotations

from typing import Dict, Iterable, Set


class DependencyGraph:
    def __init__(self) -> None:
        # cell -> set of precedent names (upstream)
        self._prec: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]) -> None:
        new = set(precedents)
        if not new:
            self._prec.pop(cell, None)
        else:
            self._prec[cell] = new

    def precedents(self, cell: str) -> Set[str]:
        p = self._prec.get(cell)
        return set(p) if p is not None else set()

    def dependents(self, cell: str) -> Set[str]:
        # cells whose precedents include `cell`
        out = set()
        for c, p in self._prec.items():
            if cell in p:
                out.add(c)
        return out

    def _reaches(self, start: str) -> Set[str]:
        seen = set()
        stack = list(self._prec.get(start, ()))
        while stack:
            c = stack.pop()
            if c in seen:
                continue
            seen.add(c)
            stack.extend(self._prec.get(c, ()))
        return seen

    def all_dependents(self, cell: str) -> Set[str]:
        return self._reaches(cell)

    def cycle_cells(self) -> Set[str]:
        out = set()
        for c in self._prec:
            if c in self._reaches(c):
                out.add(c)
        return out
