"""The spreadsheet object that stores cells and recalculates formulas."""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Set, Tuple

from .formula import (
    CYCLE,
    FormulaError,
    parse_formula,
    references,
    evaluate,
)
from .graph import DependencyGraph


def _validate_cell(name: str) -> str:
    if not isinstance(name, str):
        raise ValueError("invalid cell name")
    u = name.upper()
    if len(u) < 2 or len(u) > 4:
        raise ValueError("invalid cell name")
    i = 0
    letters = []
    while i < len(u) and u[i].isalpha():
        letters.append(u[i])
        i += 1
    digits = []
    while i < len(u) and u[i].isdigit():
        digits.append(u[i])
        i += 1
    if i != len(u) or not letters or not digits:
        raise ValueError("invalid cell name")
    col = "".join(letters)
    if len(col) != 1 or col not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        raise ValueError("invalid cell name")
    row_str = "".join(digits)
    if len(row_str) > 1 and row_str[0] == "0":
        raise ValueError("invalid cell name")
    row = int(row_str)
    if row < 1 or row > 999:
        raise ValueError("invalid cell name")
    return col + str(row)


def _rowmajor_key(name: str) -> Tuple[int, str]:
    # name is like "B12"; last letters are column, rest is row
    # column is a single letter; row is the digits
    col = ""
    row = ""
    i = 0
    while i < len(name) and name[i].isalpha():
        col += name[i]
        i += 1
    while i < len(name) and name[i].isdigit():
        row += name[i]
        i += 1
    return (int(row), col)


class Sheet:
    def __init__(self) -> None:
        self._raw: Dict[str, str] = {}
        self._tree: Dict[str, Any] = {}
        self._value: Dict[str, Any] = {}
        self._graph = DependencyGraph()
        self.evaluations = 0

    # -- public API --

    def set(self, name: str, raw: str) -> List[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")
        cname = _validate_cell(name)

        # Determine new tree/precedents *before* mutating (atomicity).
        if raw == "":
            new_tree = None
        elif raw.lstrip().startswith("="):
            new_tree = parse_formula(raw.lstrip()[1:])
        else:
            new_tree = None

        if new_tree is not None:
            try:
                new_prec = references(new_tree)
            except FormulaError:
                raise

        # Apply the new state.
        if new_tree is None:
            if raw == "":
                self._raw.pop(cname, None)
                self._tree.pop(cname, None)
                self._value.pop(cname, None)
                self._graph.set_dependencies(cname, ())
            else:
                self._raw[cname] = raw
                self._tree.pop(cname, None)
                self._graph.set_dependencies(cname, ())
                self._value[cname] = self._parse_literal(raw)
        else:
            self._raw[cname] = raw
            self._tree[cname] = new_tree
            self._graph.set_dependencies(cname, new_prec)
            self._value[cname] = None

        # Recalculate.
        self._recalculate({cname})

        # Report cells whose value may have changed, row-major.
        affected = {cname} | self._graph.all_dependents(cname)
        return sorted(affected, key=_rowmajor_key)

    def get(self, name: str) -> Any:
        cname = _validate_cell(name)
        return self._value.get(cname)

    def raw(self, name: str) -> str:
        cname = _validate_cell(name)
        return self._raw.get(cname, "")

    def cells(self) -> List[str]:
        return sorted(self._raw.keys(), key=_rowmajor_key)

    # -- internals --

    @staticmethod
    def _parse_literal(raw: str) -> Any:
        stripped = raw.strip()
        if stripped:
            s = stripped[1:] if stripped[0] == "-" else stripped
            if s:
                if "." in s:
                    parts = s.split(".")
                    if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
                        return float(stripped)
                elif s.isdigit():
                    return int(stripped)
        return raw

    def _lookup(self, name: str) -> Any:
        return self._value.get(name)

    def _recalculate(self, seed: Set[str]) -> None:
        # Cells to evaluate: seed plus transitive dependents that are formulas.
        to_eval = set(seed) | self._graph.all_dependents(seed)
        to_eval = {c for c in to_eval if c in self._tree}

        # Recompute cycle cells globally to keep values consistent.
        cycles = self._graph.cycle_cells()

        # Drop seeds and any cell on a cycle from the evaluation list.
        to_eval -= seed
        to_eval -= cycles

        # For cycle cells, set value to CYCLE and count evaluations.
        for c in cycles:
            if c in self._tree:
                self._value[c] = CYCLE
                self.evaluations += 1

        # Evaluate non-cycle formula cells in dependency order.
        ordered = self._topological_order(to_eval)
        for c in ordered:
            tree = self._tree[c]
            self._value[c] = evaluate(tree, self._lookup)
            self.evaluations += 1

        # Propagate CYCLE through dependents of cycle cells that are formula
        # cells but not themselves on a cycle (their inputs already CYCLE).
        # (Handled implicitly: evaluate reads values via _lookup, so a cell
        # whose input is CYCLE yields CYCLE. But such cells may not be in
        # `to_eval` if they weren't reached from the seed.)
        for c in self._graph.cycle_cells():
            for d in self._graph.all_dependents(c):
                if d in self._tree and d not in cycles and d not in seed:
                    # Only recompute if it wasn't already evaluated above.
                    if d not in ordered and not self._graph._prec.get(d):
                        continue
                    if d not in ordered and d not in to_eval:
                        continue
                    # If not yet evaluated this round, ensure consistency.
                    if d in ordered or d in to_eval:
                        continue
                    self._value[d] = evaluate(self._tree[d], self._lookup)
                    self.evaluations += 1

    def _topological_order(self, cells: Set[str]) -> List[str]:
        # Build a graph restricted to `cells` with edges precedent -> cell
        # (precedent must be computed first).
        in_deg = {c: 0 for c in cells}
        children = {c: set() for c in cells}
        for c in cells:
            for p in self._graph._prec.get(c, ()):
                if p in cells:
                    # p must be computed before c
                    in_deg[c] += 1
                    children[p].add(c)

        import collections

        q = collections.deque(sorted([c for c, d in in_deg.items() if d == 0], key=_rowmajor_key))
        out = []
        while q:
            c = q.popleft()
            out.append(c)
            for ch in sorted(children[c], key=_rowmajor_key):
                in_deg[ch] -= 1
                if in_deg[ch] == 0:
                    q.append(ch)
        # Any leftover cells (shouldn't happen for non-cycle cells) appended.
        for c in sorted(cells, key=_rowmajor_key):
            if c not in out:
                out.append(c)
        return out
