from fractions import Fraction
from decimal import Decimal, InvalidOperation

class CalcError(Exception):
    """Exception raised for calculator errors."""
    def __init__(self, message, position):
        super().__init__(message)
        self.position = position

class Token:
    def __init__(self, type, value, position):
        self.type = type # 'NUM', 'OP', 'PAREN', 'EOF'
        self.value = value
        self.position = position

class Lexer:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        i = 0
        n = len(self.expr)
        while i < n:
            char = self.expr[i]
            if char in ' \t':
                i += 1
                continue

            if char.isdigit():
                start = i
                i += 1
                while i < n and self.expr[i].isdigit():
                    i += 1

                if i < n and self.expr[i] == '.':
                    # Look ahead for digit after dot
                    if i + 1 < n and self.expr[i+1].isdigit():
                        i += 1 # consume dot
                        while i < n and self.expr[i].isdigit():
                            i += 1
                    else:
                        # Dot not followed by digit. 
                        # If we consumed digits, the dot is invalid if it's not part of a valid number.
                        # But the spec says '1.5.2' error at 3. 
                        # '1.5' is valid. '1.5.' -> error at 3? No, '1.5' ends at 3. Next char is '.' at 3.
                        # Actually, if we have '1.5.2', we parse '1.5' (0-3). Next char is '.' at 3.
                        # Is '1' valid? Yes. Then '.5' at 1. 
                        # Let's trace '1.5.2'. 
                        # i=0, '1'. Next '.', look ahead '5' (digit). Consume '1.5'. i=3.
                        # Loop continues. i=3, char='.'. Not digit, not space, not op. 
                        # Invalid char. Error at 3. Correct.
                        pass

                num_str = self.expr[start:i]
                try:
                    val = Fraction(Decimal(num_str))
                except (InvalidOperation, ValueError):
                    raise CalcError("Invalid number", start)
                self.tokens.append(Token('NUM', val, start))
                continue

            if char in '+-*/()':
                t_type = 'PAREN' if char in '()' else 'OP'
                self.tokens.append(Token(t_type, char, i))
                i += 1
                continue

            raise CalcError(f"Invalid character '{char}'", i)

        self.tokens.append(Token('EOF', None, n))

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        expr = self.parse_expr()
        if self.current().type != 'EOF':
            raise CalcError("Unexpected token", self.current().position)
        return expr

    def parse_expr(self):
        # + -
        left = self.parse_term()
        while self.current().type == 'OP' and self.current().value in ('+', '-'):
            op_tok = self.consume()
            right = self.parse_term()
            left = ('bin', op_tok.value, left, right, op_tok.position)
        return left

    def parse_term(self):
        # * /
        left = self.parse_factor()
        while self.current().type == 'OP' and self.current().value in ('*', '/'):
            op_tok = self.consume()
            right = self.parse_factor()
            left = ('bin', op_tok.value, left, right, op_tok.position)
        return left

    def parse_factor(self):
        tok = self.current()

        # Unary minus
        if tok.type == 'OP' and tok.value == '-':
            self.consume()
            operand = self.parse_factor()
            return ('neg', operand)

        # Parentheses
        if tok.type == 'PAREN' and tok.value == '(':
            self.consume()
            expr = self.parse_expr()
            if self.current().type != 'PAREN' or self.current().value != ')':
                raise CalcError("Expected ')'", self.current().position)
            self.consume()
            return expr

        # Number
        if tok.type == 'NUM':
            self.consume()
            return ('num', tok.value)

        # Error: unexpected token
        raise CalcError("Unexpected token", tok.position)

def eval_ast(node):
    if node[0] == 'num':
        return node[1]

    if node[0] == 'neg':
        return -eval_ast(node[1])

    if node[0] == 'bin':
        op, left, right, pos = node[1], node[2], node[3], node[4]
        l_val = eval_ast(left)
        r_val = eval_ast(right)

        if op == '+': return l_val + r_val
        if op == '-': return l_val - r_val
        if op == '*': return l_val * r_val
        if op == '/':
            if r_val == 0:
                raise CalcError("Division by zero", pos)
            return l_val / r_val

    raise CalcError("Invalid AST", 0)

def evaluate(expr: str) -> Fraction:
    if not expr or expr.strip() == '':
        raise CalcError("Empty expression", 0)

    try:
        lexer = Lexer(expr)
        parser = Parser(lexer.tokens)
        ast = parser.parse()
        return eval_ast(ast)
    except CalcError:
        raise
    except Exception as e:
        # Catch any other unexpected errors and wrap them if necessary, 
        # but spec implies we should be robust.
        raise CalcError(str(e), 0)
