            if char in '+-*/()':
                t_type = 'PAREN' if char in '()' else 'OP'
                self.tokens.append(Token(t_type, char, i))
                i += 1
                continue

            raise CalcError(f"Invalid character '{char}'", i)

        self.tokens.append(Token('EOF', None, n))

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        expr = self.parse_expr()
        if self.current().type != 'EOF':
            raise CalcError("Unexpected token", self.current().position)
        return expr

    def parse_expr(self):
        # + -
        left = self.parse_term()
        while self.current().type == 'OP' and self.current().value in ('+', '-'):
            op_tok = self.consume()
            right = self.parse_term()
            left = ('bin', op_tok.value, left, right, op_tok.position)
        return left

    def parse_term(self):
        # * /
        left = self.parse_factor()
        while self.current().type == 'OP' and self.current().value in ('*', '/'):
            op_tok = self.consume()
            right = self.parse_factor()
            left = ('bin', op_tok.value, left, right, op_tok.position)
        return left

    def parse_factor(self):
        tok = self.current()

        # Unary minus
        if tok.type == 'OP' and tok.value == '-':
            self.consume()
            operand = self.parse_factor()
            return ('neg', operand)

        # Parentheses
        if tok.type == 'PAREN' and tok.value == '(':
            self.consume()
            expr = self.parse_expr()
            if self.current().type != 'PAREN' or self.current().value != ')':
                raise CalcError("Expected ')'", self.current().position)
            self.consume()
            return expr

        # Number
        if tok.type == 'NUM':
            self.consume()
            return ('num', tok.value)

        # Error: unexpected token
        raise CalcError("Unexpected token", tok.position)

def eval_ast(node):
    if node[0] == 'num':
        return node[1]

    if node[0] == 'neg':
        return -eval_ast(node[1])

    if node[0] == 'bin':
        op, left, right, pos = node[1], node[2], node[3], node[4]
        l_val = eval_ast(left)
        r_val = eval_ast(right)

        if op == '+': return l_val + r_val
        if op == '-': return l_val - r_val
        if op == '*': return l_val * r_val
        if op == '/':
            if r_val == 0:
                raise CalcError("Division by zero", pos)
            return l_val / r_val

    raise CalcError("Invalid AST", 0)

def evaluate(expr: str) -> Fraction:
    if not expr or expr.strip() == '':
        raise CalcError("Empty expression", 0)

    try:
        lexer = Lexer(expr)
        parser = Parser(lexer.tokens)
        ast = parser.parse()
        return eval_ast(ast)
    except CalcError:
        raise
    except Exception as e:
        # Catch any other unexpected errors and wrap them if necessary, 
        # but spec implies we should be robust.
        raise CalcError(str(e), 0)

import unittest
from toposort import toposort, CycleError


class TestTopoSort(unittest.TestCase):
    def test_empty_graph(self):
        self.assertEqual(toposort({}), [])

    def test_simple_sort(self):
        graph = {'b': [], 'a': [], 'c': ['b']}
        self.assertEqual(toposort(graph), ['a', 'b', 'c'])

    def test_lexicographical_ties(self):
        graph = {'z': [], 'a': ['z']}
        self.assertEqual(toposort(graph), ['z', 'a'])

        graph = {'c': [], 'b': ['c'], 'a': ['c', 'b']}
        self.assertEqual(toposort(graph), ['c', 'b', 'a'])

        graph = {'b': [], 'a': [], 'c': ['a', 'b']}
        self.assertEqual(toposort(graph), ['a', 'b', 'c'])

    def test_cycle_detection_simple(self):
        graph = {'a': ['b'], 'b': ['a']}
        with self.assertRaises(CycleError) as cm:
            toposort(graph)
        self.assertEqual(set(cm.exception.cycle), {'a', 'b'})

    def test_cycle_detection_self(self):
        graph = {'a': ['a']}
        with self.assertRaises(CycleError) as cm:
            toposort(graph)
        self.assertEqual(cm.exception.cycle, ['a'])

    def test_graph_not_modified(self):
        graph = {'b': [], 'a': ['b']}
        original_keys = set(graph.keys())
        original_deps = {k: set(v) for k, v in graph.items()}

        toposort(graph)

        self.assertEqual(set(graph.keys()), original_keys)
        for k, v in graph.items():
            self.assertEqual(set(v), original_deps[k])

    def test_multiple_cycles(self):
        # Graph with two cycles: a->b->a and c->d->c
        # toposort should raise CycleError with one of the cycles
        graph = {
            'a': ['b'],
            'b': ['a'],
            'c': ['d'],
            'd': ['c']
        }
        with self.assertRaises(CycleError) as cm:
            toposort(graph)
        cycle = cm.exception.cycle
        self.assertTrue(set(cycle).issubset({'a', 'b', 'c', 'd'}))
        self.assertTrue(len(cycle) > 0)

        # Verify it is a valid cycle in the graph
        for i in range(len(cycle)):
            u = cycle[i]
            v = cycle[(i + 1) % len(cycle)]
            # u depends on v? In the problem, graph[u] contains dependencies of u.
            # So if u depends on v, v is in graph[u].
            # But the cycle definition in the prompt says: n1 depends on n2, n2 depends on n3...
            # So if cycle is [a, b], a depends on b, b depends on a.
            # In graph: a -> [b], b -> [a].
            # Check if next node is in dependencies of current node
            self.assertIn(v, graph[u])

if __name__ == '__main__':
    unittest.main()

