import collections.abc
from .lexer import TemplateRenderError
from .parser import (
    Node, TextNode, VarNode, ForNode, IfNode,
    ExprNode, LiteralNode, PathNode, FilterNode, CompareNode,
    AndNode, OrNode, NotNode, parse
)

# -----------------------------------------------------------------------------
# Filters
# -----------------------------------------------------------------------------

def _output_text(value):
    """Convert a value to its output text representation."""
    if value is None:
        return ""
    return str(value)

def filter_upper(value, arg):
    return _output_text(value).upper()

def filter_lower(value, arg):
    return _output_text(value).lower()

def filter_trim(value, arg):
    return _output_text(value).strip()

def filter_length(value, arg):
    if value is None:
        return 0
    if isinstance(value, str):
        return len(value)
    if isinstance(value, collections.abc.Sized):
        return len(value)
    # For types without __len__ but are iterable? Spec says "render error" for invalid ops.
    # "length: len(value); None gives 0." 
    # If value is int, len(int) raises TypeError. Spec: "A filter applied to a value it cannot handle ... is a render error."
    try:
        return len(value)
    except TypeError:
        raise TemplateRenderError(f"Filter 'length' cannot be applied to {type(value).__name__}", 0)

def filter_first(value, arg):
    if value is None:
        return None
    if isinstance(value, (list, tuple, str)) and len(value) > 0:
        return value[0]
    if isinstance(value, collections.abc.Iterable):
        it = iter(value)
        try:
            return next(it)
        except StopIteration:
            return None
    raise TemplateRenderError(f"Filter 'first' cannot be applied to {type(value).__name__}", 0)

def filter_last(value, arg):
    if value is None:
        return None
    if isinstance(value, (list, tuple, str)) and len(value) > 0:
        return value[-1]
    if isinstance(value, collections.abc.Iterable):
        items = list(value)
        if items:
            return items[-1]
        return None
    raise TemplateRenderError(f"Filter 'last' cannot be applied to {type(value).__name__}", 0)

def filter_reverse(value, arg):
    if value is None:
        return None
    if isinstance(value, str):
        return value[::-1]
    if isinstance(value, (list, tuple)):
        return value[::-1]
    # "a string reversed, or a list of any other value's items in reverse order"
    if isinstance(value, collections.abc.Iterable):
        return list(value)[::-1]
    raise TemplateRenderError(f"Filter 'reverse' cannot be applied to {type(value).__name__}", 0)

def filter_join(value, arg):
    if value is None:
        return ""
    if arg is None:
        raise TemplateRenderError("Filter 'join' requires a string argument", 0)

    # "the output text of each item, joined with sep"
    # If value is iterable
    if isinstance(value, collections.abc.Iterable):
        parts = [_output_text(item) for item in value]
        return str(arg).join(parts)

    raise TemplateRenderError(f"Filter 'join' cannot be applied to {type(value).__name__}", 0)

def filter_default(value, arg):
    if value is None or (isinstance(value, str) and value == ""):
        return arg
    return value

def filter_truncate(value, arg):
    if arg is None:
        raise TemplateRenderError("Filter 'truncate' requires an integer argument", 0)

    text = _output_text(value)
    n = arg

    if not isinstance(n, int):
         # Spec: "argument of the wrong kind ... is a syntax error" in parser? 
         # But spec also says "argument of the wrong kind ... is a syntax error" in Filters section.
         # If it passes parser, it might be wrong at runtime? 
         # "an argument of the wrong kind ... is a syntax error". This implies parser handles it.
         # If we get here, assume it's valid or raise render error.
         pass

    if len(text) > n:
        return text[:n] + "..."
    return text

def filter_items(value, arg):
    if value is None:
        return []
    if isinstance(value, collections.abc.Mapping):
        return list(value.items())
    raise TemplateRenderError(f"Filter 'items' cannot be applied to {type(value).__name__}", 0)

FILTERS = {
    "upper": filter_upper,
    "lower": filter_lower,
    "trim": filter_trim,
    "length": filter_length,
    "first": filter_first,
    "last": filter_last,
    "reverse": filter_reverse,
    "join": filter_join,
    "default": filter_default,
    "truncate": filter_truncate,
    "items": filter_items,
}

# -----------------------------------------------------------------------------
# Evaluation Helpers
# -----------------------------------------------------------------------------

def _resolve_path(context, parts):
    """
    Resolve a variable path (list of segments) against the context.
    Returns None if not found or invalid.
    """
    # The first part is the root name
    # parts is a list of strings/ints from PathNode.parts
    # PathNode.parts structure: from parser, it seems to be a list of segments.
    # Let's assume parts is like ['user', 'name'] or ['rows', '0', 'title']

    current = context

    for i, segment in enumerate(parts):
        if i == 0:
            # Lookup in context
            if segment in current:
                current = current[segment]
            else:
                return None
            continue

        # Apply segment to current value
        if current is None:
            return None

        # Mapping
        if isinstance(current, collections.abc.Mapping):
            # Segment is a string
            key = str(segment)
            if key in current:
                current = current[key]
            else:
                return None

        elif isinstance(current, (list, tuple)):
            # Segment should be integer index
            # Spec: "with an integer segment"
            # Segment from PathNode might be a string representing int? 
            # "rows.0" -> segment '0'
            try:
                idx = int(segment)
                if 0 <= idx < len(current):
                    current = current[idx]
                else:
                    return None
            except ValueError:
                return None

        else:
            # Attribute access
            # "with a name segment that does not start with _"
            if isinstance(segment, str):
                if segment.startswith('_'):
                    return None
                current = getattr(current, segment, None)
            else:
                return None

    return current

def _get_lineno(node):
    return getattr(node, 'lineno', 0)

def _eval_expr(node, context):
    """
    Evaluate an expression node.
    Returns the value (not stringified).
    """
    if isinstance(node, LiteralNode):
        return node.value

    if isinstance(node, PathNode):
        return _resolve_path(context, node.parts)

    if isinstance(node, FilterNode):
        val = _eval_expr(node.target, context)
        filter_name = node.name
        if filter_name not in FILTERS:
            # Should have been caught by parser as syntax error
            raise TemplateRenderError(f"Unknown filter '{filter_name}'", _get_lineno(node))

        try:
            return FILTERS[filter_name](val, node.arg)
        except TemplateRenderError:
            raise
        except Exception as e:
            raise TemplateRenderError(f"Error in filter '{filter_name}': {e}", _get_lineno(node))

    if isinstance(node, CompareNode):
        left = _eval_expr(node.left, context)
        right = _eval_expr(node.right, context)
        op = node.op
        try:
            if op == '==': return left == right
            if op == '!=': return left != right
            if op == '<': return left < right
            if op == '<=': return left <= right
            if op == '>': return left > right
            if op == '>=': return left >= right
        except TypeError:
            raise TemplateRenderError(f"Cannot compare {type(left).__name__} and {type(right).__name__}", _get_lineno(node))

    if isinstance(node, AndNode):
        left_val = _eval_expr(node.left, context)
        if not left_val:
            return left_val
        return _eval_expr(node.right, context)

    if isinstance(node, OrNode):
        left_val = _eval_expr(node.left, context)
        if left_val:
            return left_val
        return _eval_expr(node.right, context)

    if isinstance(node, NotNode):
        return not _eval_expr(node.operand, context)

    raise TemplateRenderError(f"Unknown expression node type: {type(node).__name__}", _get_lineno(node))

def _render_nodes(nodes, context):
    """
    Render a list of nodes into a string.
    """
    output = []
    for node in nodes:
        if isinstance(node, TextNode):
            output.append(node.text)

        elif isinstance(node, VarNode):
            val = _eval_expr(node.expr, context)
            output.append(_output_text(val))

        elif isinstance(node, IfNode):
            # conditions: list of (cond_expr, body_nodes)
            # last element might be (None, else_body)
            matched = False
            for cond_expr, body_nodes in node.conditions:
                if cond_expr is None:
                    # This is the else block
                    if not matched:
                        output.extend(_render_nodes(body_nodes, context))
                        matched = True
                else:
                    # This is a condition
                    val = _eval_expr(cond_expr, context)
                    if val:
                        output.extend(_render_nodes(body_nodes, context))
                        matched = True
                        break # Short-circuit, first true branch

        elif isinstance(node, ForNode):
            # Evaluate the iterable expression
            items_val = _eval_expr(node.expr, context)

            # Handle iteration
            if items_val is None:
                items = []
            elif isinstance(items_val, collections.abc.Mapping):
                items = list(items_val.keys())
            elif isinstance(items_val, (list, tuple, str)):
                items = items_val
            elif isinstance(items_val, collections.abc.Iterable):
                items = list(items_val)
            else:
                raise TemplateRenderError(f"Cannot iterate over {type(items_val).__name__}", _get_lineno(node))

            count = len(items)

            if count == 0:
                if node.else_body:
                    output.extend(_render_nodes(node.else_body, context))
            else:
                # Create local scope for loop
                # "These two names hide outer values of the same names only inside the body"
                loop_ctx = dict(context)

                for i, item in enumerate(items):
                    loop_data = {
                        "index": i + 1,
                        "index0": i,
                        "first": i == 0,
                        "last": i == count - 1,
                        "length": count,
                    }

                    # Shadow outer variables
                    loop_ctx[node.var_name] = item
                    loop_ctx["loop"] = loop_data

                    output.extend(_render_nodes(node.body, loop_ctx))

        else:
            # Unknown node type at render time
            raise TemplateRenderError(f"Unknown node type: {type(node).__name__}", _get_lineno(node))

    return "".join(output)

# -----------------------------------------------------------------------------
# Public API
# -----------------------------------------------------------------------------

class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        # "a keyword argument wins over a context entry of the same name"
        # "Rendering never modifies the dict passed in"
        if context is None:
            ctx = {}
        else:
            ctx = dict(context)

        ctx.update(kwargs)

        return _render_nodes(self.nodes, ctx)

def render(source: str, context: dict | None = None, **kwargs) -> str:
    """
    Render a template source string with the given context.
    """
    return Template(source).render(context, **kwargs)
